package org.marketreview.nativeapp;
import android.content.Context;import android.view.*;import android.widget.*;import android.os.Build;import org.json.*;import java.util.*;
final class IndustryVersionScreen extends LinearLayout{
 final BusinessStore store;final Spinner archives,versions,compare,mode;final TextView state;final LinearLayout content;JSONArray groups=new JSONArray();final List<String> versionIds=new ArrayList<>(),compareIds=new ArrayList<>();boolean updating;int viewMode;final LinearLayout selectors;
 IndustryVersionScreen(Context context,BusinessStore store,Runnable back,Runnable backup){super(context);this.store=store;setOrientation(VERTICAL);setTag("industryVersionScreen");LinearLayout actions=new LinearLayout(context);addView(actions);button(actions,"返回原文关系",back);button(actions,"重读原件",this::reload);button(actions,"统一备份 / 恢复",backup);mode=new Spinner(context);mode.setTag("industryReportMode");choices(mode,Arrays.asList("完整原文","版本差异","所选版本环节图","原配置 / 运行"));selectors=new LinearLayout(context);addView(selectors);selectors.addView(mode);archives=new Spinner(context);archives.setTag("industryReportArchive");selectors.addView(archives);versions=new Spinner(context);versions.setTag("industryReportVersion");selectors.addView(versions);compare=new Spinner(context);compare.setTag("industryReportCompare");selectors.addView(compare);layoutSelectors();ScrollView scroll=new ScrollView(context);content=new LinearLayout(context);content.setOrientation(VERTICAL);scroll.addView(content);addView(scroll,new LayoutParams(-1,0,1));state=new TextView(context);state.setTag("industryReportState");state.setSingleLine(true);state.setEllipsize(android.text.TextUtils.TruncateAt.END);addView(state);listen(mode,()->{viewMode=mode.getSelectedItemPosition();show();});listen(archives,this::groupChanged);listen(versions,this::show);listen(compare,this::show);reload();}
 void layoutSelectors(){boolean wide=getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE;selectors.setOrientation(wide?HORIZONTAL:VERTICAL);for(int i=0;i<selectors.getChildCount();i++)selectors.getChildAt(i).setLayoutParams(wide?new LayoutParams(0,-2,1):new LayoutParams(-1,-2));}
 @Override protected void onConfigurationChanged(android.content.res.Configuration config){super.onConfigurationChanged(config);layoutSelectors();}
 void button(LinearLayout where,String text,Runnable action){Button b=new Button(getContext());b.setText(text);b.setEnabled(action!=null);where.addView(b,new LayoutParams(0,-2,1));if(action!=null)b.setOnClickListener(v->{if(isShown())action.run();});}
 void listen(Spinner spinner,Runnable action){spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> a,View v,int n,long id){if(!updating)action.run();}public void onNothingSelected(AdapterView<?> a){}});}
 void choices(Spinner s,List<String> values){s.setAdapter(new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_dropdown_item,values){@Override public View getView(int position,View convertView,ViewGroup parent){TextView label=(TextView)super.getView(position,convertView,parent);label.setSingleLine(true);label.setEllipsize(android.text.TextUtils.TruncateAt.END);return label;}});}
 JSONObject group(){int at=archives.getSelectedItemPosition();return at>=0&&at<groups.length()?groups.optJSONObject(at):new JSONObject();}
 void reload(){try{String saved=group().optString("key");JSONArray reports=new JSONArray(),topics=new JSONArray();if(Build.VERSION.SDK_INT>=35){JSONArray rows=new IndustryArchiveStore(getContext().getDatabasePath(store.getDatabaseName())).catalogRecords();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if("reports".equals(row.optString("kind")))reports.put(IndustryArchiveState.record(row));if("topics".equals(row.optString("kind")))topics.put(IndustryArchiveState.record(row));}}else{reports=store.read("reports");topics=store.read("topics");}groups=IndustryVersionCatalog.catalog(reports,topics);List<String> names=new ArrayList<>();int selected=0;for(int i=0;i<groups.length();i++){JSONObject g=groups.getJSONObject(i);names.add(g.optString("name")+(g.optBoolean("complete")?" · 完整档案":" · 已有正文"));if(saved.equals(g.optString("key")))selected=i;}updating=true;choices(archives,names);archives.setSelection(selected);updating=false;groupChanged();}catch(Exception e){updating=false;state.setText(e.getMessage());}}
 void groupChanged(){try{JSONObject g=group();JSONArray values=g.optJSONArray("versions");List<String> labels=new ArrayList<>(),comparison=new ArrayList<>();versionIds.clear();compareIds.clear();comparison.add("不对比");compareIds.add("");int current=0;if(values!=null)for(int i=0;i<values.length();i++){JSONObject v=values.getJSONObject(i);String id=v.getString("id"),label="#"+v.optInt("sequence")+" · "+id+" · "+v.optString("createdAt");labels.add(label);comparison.add(label);versionIds.add(id);compareIds.add(id);if(id.equals(g.optString("currentVersionId")))current=i;}updating=true;choices(versions,labels);versions.setSelection(current);choices(compare,comparison);updating=false;show();}catch(Exception e){updating=false;state.setText(e.getMessage());}}
 void segment(String text,String tag){segment(content,text,tag);}
 void segment(LinearLayout where,String text,String tag){for(int at=0;at<text.length();){int end=Math.min(text.length(),at+32768);if(end<text.length()&&Character.isHighSurrogate(text.charAt(end-1)))end--;TextView t=new TextView(getContext()){@Override public boolean onPreDraw(){return !isShown()||getWidth()<=0||super.onPreDraw();}};t.setTag(tag);t.setTextSize(13);t.setTextIsSelectable(true);t.setBreakStrategy(android.text.Layout.BREAK_STRATEGY_SIMPLE);t.setHyphenationFrequency(android.text.Layout.HYPHENATION_FREQUENCY_NONE);t.setText(text.substring(at,end));where.addView(t);at=end;}}
 void show(){try{content.removeAllViews();JSONObject g=group();if(groups.length()==0){state.setText("暂无旧产业报告；可在统一备份中预览完整原件。");return;}int n=versions.getSelectedItemPosition(),c=compare.getSelectedItemPosition();String id=n>=0&&n<versionIds.size()?versionIds.get(n):"",other=c>=0&&c<compareIds.size()?compareIds.get(c):"";if(viewMode==0){segment(IndustryVersionCatalog.report(g,id),"industryReportOriginal");if(!other.isEmpty())segment("对比版本\n"+IndustryVersionCatalog.report(g,other),"industryReportComparison");}
 else if(viewMode==1)segment(other.isEmpty()?"请选择对比版本":IndustryVersionCatalog.difference(g,other,id).toString(2),"industryVersionDifference");
 else if(viewMode==3)segment(IndustryVersionCatalog.context(g),"industryReportContext");
 else graph(g,id);
 state.setText((g.optBoolean("complete")?"完整原件已核对":"已有正文，完整关联未提供")+" · 原当前指针："+(g.isNull("currentVersionId")?"无 / 未提供":g.optString("currentVersionId")));}catch(Exception e){state.setText(e.getMessage());}}
 void setTopic(String id){if(id.startsWith("legacy-topic:"))id=id.substring(13);for(int i=0;i<groups.length();i++)if(id.equals(groups.optJSONObject(i).optString("topicId"))){archives.setSelection(i);return;}}
 void graph(JSONObject g,String id)throws Exception{
  JSONArray rows=IndustryVersionCatalog.selectedRelations(g,id);IndustryGraph graph=new IndustryGraph(getContext());graph.setTag("industryVersionGraph");JSONArray displayed=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i),shown=new JSONObject();for(Iterator<String> keys=row.keys();keys.hasNext();){String key=keys.next();shown.put(key,row.get(key));}if("legacyVerified".equals(shown.optString("status")))shown.put("status","legacy");displayed.put(shown);}graph.setRows(displayed);if(getContext() instanceof MainActivity)graph.setDarkTheme(((MainActivity)getContext()).darkTheme());HorizontalScrollView scroll=new HorizontalScrollView(getContext());scroll.addView(graph);content.addView(scroll);Spinner selected=new Spinner(getContext());selected.setTag("industryVersionRelation");List<String> labels=new ArrayList<>();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);labels.add(row.optString("companyName")+" · "+row.optString("relationId"));}choices(selected,labels);content.addView(selected);LinearLayout detail=new LinearLayout(getContext());detail.setOrientation(VERTICAL);content.addView(detail);
  Runnable show=()->{try{detail.removeAllViews();int at=selected.getSelectedItemPosition();if(at<0||at>=rows.length())return;JSONObject row=rows.getJSONObject(at);graph.setSelected(row.getString("key"));segment(detail,(row.optBoolean("bodyAvailable")?"留存正文中的引文逐字匹配；仍需当前事实复核":"引用缺件或未逐字匹配；不得视为当前已核验")+"\n"+row.toString(2),"industryVersionEvidence");}catch(Exception e){state.setText(e.getMessage());}};
  listen(selected,show);graph.onSelected=key->{for(int i=0;i<rows.length();i++)if(key.equals(rows.optJSONObject(i).optString("key"))){selected.setSelection(i);return;}};show.run();
 }
}

